int pos = 0;
while (pos < leaf->num_keys && leaf->keys[pos] < key) {
    pos++;
}

// Shift existing elements to the right
for (int i = leaf->num_keys; i > pos; i--) {
    leaf->keys[i] = leaf->keys[i-1];
    leaf->data_ptrs[i] = leaf->data_ptrs[i-1];
}

// Insert the new key and data pointer
leaf->keys[pos] = key;
leaf->data_ptrs[pos] = filePtr;
leaf->num_keys++;

